        nx, ny = sx + dx, sy + dy
        if not ok(nx, ny):
            continue
        score = 0
        if (nx, ny) in res_set:
            score += 1000000
        if opp_row is not None and ny == opp_row:
            score += 2000
        d_self = min(man(nx, ny, rx, ry) for rx, ry in resources)
        d_opp = min(man(ox, oy, rx, ry) for rx, ry in resources)
        score += (d_opp - d_self) * 50
        score -= man(nx, ny, ox, oy) * 5
        if score > best_score:
            best_score = score
            best_move = (dx, dy)

    if ok(sx, sy):
        if best_move == (0, 0):
            return [0, 0]
    if ok(sx + best_move[0], sy + best_move[1]):
        return [best_move[0], best_move[1]]

    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if ok(nx, ny):
            return [dx, dy]
    return [0, 0]

